const raw = $input.first().json;
const body = raw.body || raw;

function normalizePhone(phone) {
  if (!phone) return '';
  const d = String(phone).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  return d ? '+1' + d : '';
}

const score = (body.score || body.immo_ia_score || '').toLowerCase();
const skip = score === 'hot' || body.do_not_call || body.explicit_refusal || body.stop_nurture;
const call_answered = body.call_answered === true || body.call_answered === 'true' || (parseInt(body.call_duration_seconds || 0, 10) >= 25);
const skip_initial_call = body.skip_initial_call === true || body.skip_initial_call === 'true';

const ctx = {
  ...body,
  lead_id: body.lead_id || body.odoo_lead_id,
  phone: normalizePhone(body.phone),
  first_name: (body.first_name || body.lead_name || 'Bonjour').split(' ')[0],
  full_address: body.full_address || body.property_address || '',
  neighborhood: body.neighborhood || (body.full_address || '').split(',')[0] || 'votre secteur',
  season: body.season || 'printemps',
  market_days: body.market_days || '45',
  score,
  call_answered,
  skip_nurture: skip,
  skip_initial_call,
  total_call_attempts: parseInt(body.total_call_attempts || body.immo_total_call_attempts || 0, 10),
  n8n_base: '{{N8N_WEBHOOK_BASE}}',
};

return [{ json: ctx }];

const j = $input.first().json;
const token = '{{META_IMMO_WEBHOOK_TOKEN}}';
await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://intellixcrm.com/api/immo/lead/update',
  headers: { 'X-Immo-Webhook-Token': token, 'Content-Type': 'application/json' },
  body: { lead_id: j.lead_id, start_nurture: true, nurture_step: 10 },
  json: true,
});
return [{ json: j }];

const c = $('1 Préparer contexte').first().json;
const sid = '{{TWILIO_ACCOUNT_SID}}';
const auth = Buffer.from(sid + ':{{TWILIO_AUTH_TOKEN}}').toString('base64');
const from = '{{TWILIO_FROM_IMMO}}';
const msg = `Bonjour ${c.first_name}! 👋\n\nJe viens d'essayer de vous joindre concernant votre évaluation marchande gratuite.\n\nRépondez simplement OUI ici et je vous rappelle dans les prochaines minutes!\n\n— Sophie, Maison Recherchée.`;
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(c.phone)}&From=${encodeURIComponent(from)}&Body=${encodeURIComponent(msg)}`,
});
return [{ json: c }];

