const c = $('1 Préparer contexte').item.json;
function torontoNow() {
  return new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Toronto' }));
}
function minutesUntil(dayOffset, hour, minute = 0) {
  const now = torontoNow();
  const target = new Date(now);
  target.setDate(target.getDate() + dayOffset);
  target.setHours(hour, minute, 0, 0);
  let m = Math.round((target - now) / 60000);
  return m < 1 ? 1 : m;
}
return [{ json: { ...c, wait_minutes: minutesUntil(1, 10), relance_number: 1, nurture_step: 11 } }];

